import{_ as l,W as o,s as c,u as r,ah as i,I as p,Z as n,w as s,A as t}from"./chunks/framework.B4JzB-Td.js";import"./chunks/theme.Xs8fIzCW.js";const k=JSON.parse('{"title":"如何保护 Ubuntu 16.04 上的 NGINX Web 服务器 | LCTT x X-CMD","titleTemplate":false,"description":"如何保护 Ubuntu 16.04 上的 NGINX Web 服务器 | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何保护 Ubuntu 16.04 上的 NGINX Web 服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何保护 Ubuntu 16.04 上的 NGINX Web 服务器 | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170628 Encryption How To Secure an NGINX web server on Ubuntu 16.04","title":"如何保护 Ubuntu 16.04 上的 NGINX Web 服务器","tag":"201708"},"relativePath":"201708/20170628 Encryption How To Secure an NGINX web server on Ubuntu 16.04.md","filePath":"[post].md"}'),d={name:"201708/20170628 Encryption How To Secure an NGINX web server on Ubuntu 16.04.md"};function u(b,e,h,g,v,m){const a=o("Link");return r(),c("div",null,[e[17]||(e[17]=i('<h1 id="如何保护-ubuntu-16-04-上的-nginx-web-服务器" tabindex="-1">如何保护 Ubuntu 16.04 上的 NGINX Web 服务器 <a class="header-anchor" href="#如何保护-ubuntu-16-04-上的-nginx-web-服务器" aria-label="Permalink to 如何保护 Ubuntu 16.04 上的 NGINX Web 服务器">​</a></h1><p><img src="https://www.unixmen.com/wp-content/uploads/2017/06/le-logo-standard.png" alt="Let&#39;s Encrypt Encryption CA" title="le-logo-standard"></p><h3 id="什么是-let-s-encrypt" tabindex="-1">什么是 Let’s Encrypt <a class="header-anchor" href="#什么是-let-s-encrypt" aria-label="Permalink to 什么是 Let’s Encrypt">​</a></h3>',3)),p("p",null,[n(a,{href:"https://letsencrypt.org/"},{default:t(()=>e[0]||(e[0]=[s("Let’s Encrypt")])),_:1}),e[2]||(e[2]=s(" 是互联网安全研究组织 （ISRG） 提供的免费证书认证机构。它提供了一种轻松自动的方式来获取免费的 SSL/TLS 证书 - 这是在 Web 服务器上启用加密和 HTTPS 流量的必要步骤。获取和安装证书的大多数步骤可以通过使用名为 ")),n(a,{href:"https://certbot.eff.org/"},{default:t(()=>e[1]||(e[1]=[s("Certbot")])),_:1}),e[3]||(e[3]=s(" 的工具进行自动化。"))]),e[18]||(e[18]=i(`<p>特别地，该软件可在可以使用 shell 的服务器上使用：换句话说，它可以通过 SSH 连接使用。</p><p>在本教程中，我们将看到如何使用 <code>certbot</code> 获取免费的 SSL 证书，并在 Ubuntu 16.04 服务器上使用 Nginx。</p><h3 id="安装-certbot" tabindex="-1">安装 Certbot <a class="header-anchor" href="#安装-certbot" aria-label="Permalink to 安装 Certbot">​</a></h3><p>第一步是安装 <code>certbot</code>，该软件客户端可以几乎自动化所有的过程。 Certbot 开发人员维护自己的 Ubuntu 仓库，其中包含比 Ubuntu 仓库中存在的软件更新的软件。</p><p>添加 Certbot 仓库：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># add-apt-repository ppa:certbot/certbot</span></span></code></pre></div><p>接下来，更新 APT 源列表：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># apt-get update</span></span></code></pre></div><p>此时，可以使用以下 <code>apt</code> 命令安装 <code>certbot</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># apt-get install certbot</span></span></code></pre></div><p>Certbot 现已安装并可使用。</p><h3 id="获得证书" tabindex="-1">获得证书 <a class="header-anchor" href="#获得证书" aria-label="Permalink to 获得证书">​</a></h3><p>有各种 Certbot 插件可用于获取 SSL 证书。这些插件有助于获取证书，而证书的安装和 Web 服务器配置都留给管理员。</p><p>我们使用一个名为 <strong>Webroot</strong> 的插件来获取 SSL 证书。</p><p>在有能力修改正在提供的内容的情况下，建议使用此插件。在证书颁发过程中不需要停止 Web 服务器。</p><h4 id="配置-nginx" tabindex="-1">配置 NGINX <a class="header-anchor" href="#配置-nginx" aria-label="Permalink to 配置 NGINX">​</a></h4><p>Webroot 会在 Web 根目录下的 <code>.well-known</code> 目录中为每个域创建一个临时文件。在我们的例子中，Web 根目录是 <code>/var/www/html</code>。确保该目录在 Let’s Encrypt 验证时可访问。为此，请编辑 NGINX 配置。使用文本编辑器打开 <code>/etc/nginx/sites-available/default</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># $EDITOR /etc/nginx/sites-available/default</span></span></code></pre></div><p>在该文件中，在 <code>server</code> 块内，输入以下内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> location ~ /.well-known {</span></span>
<span class="line"><span>    allow all;</span></span>
<span class="line"><span> }</span></span></code></pre></div><p>保存，退出并检查 NGINX 配置：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># nginx -t</span></span></code></pre></div><p>没有错误的话应该会显示如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nginx: the configuration file /etc/nginx/nginx.conf syntax is ok</span></span>
<span class="line"><span>nginx: configuration file /etc/nginx/nginx.conf test is successful</span></span></code></pre></div><p>重启 NGINX：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># systemctl restart nginx</span></span></code></pre></div><h4 id="使用-certbot-获取证书" tabindex="-1">使用 Certbot 获取证书 <a class="header-anchor" href="#使用-certbot-获取证书" aria-label="Permalink to 使用 Certbot 获取证书">​</a></h4><p>下一步是使用 Certbot 的 Webroot 插件获取新证书。在本教程中，我们将保护示例域 www.example.com。需要指定应由证书保护的每个域。执行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># certbot certonly --webroot --webroot-path=/var/www/html -d www.example.com</span></span></code></pre></div><p>在此过程中，Cerbot 将询问有效的电子邮件地址，用于进行通知。还会要求与 EFF 分享，但这不是必需的。在同意服务条款之后，它将获得一个新的证书。</p><p>最后，目录 <code>/etc/letsencrypt/archive</code> 将包含以下文件：</p><ul><li><code>chain.pem</code>：Let’s Encrypt 加密链证书。</li><li><code>cert.pem</code>：域名证书。</li><li><code>fullchain.pem</code>：<code>cert.pem</code>和 <code>chain.pem</code> 的组合。</li><li><code>privkey.pem</code>：证书的私钥。</li></ul><p>Certbot 还将创建符号链接到 <code>/etc/letsencrypt/live/domain_name/</code> 中的最新证书文件。这是我们将在服务器配置中使用的路径。</p><h3 id="在-nginx-上配置-ssl-tls" tabindex="-1">在 NGINX 上配置 SSL/TLS <a class="header-anchor" href="#在-nginx-上配置-ssl-tls" aria-label="Permalink to 在 NGINX 上配置 SSL/TLS">​</a></h3><p>下一步是服务器配置。在 <code>/etc/nginx/snippets/</code> 中创建一个新的代码段。 <strong>snippet</strong> 是指一段配置，可以包含在虚拟主机配置文件中。如下创建一个新的文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># $EDITOR /etc/nginx/snippets/secure-example.conf</span></span></code></pre></div><p>该文件的内容将指定证书和密钥位置。粘贴以下内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ssl_certificate /etc/letsencrypt/live/domain_name/fullchain.pem;</span></span>
<span class="line"><span>ssl_certificate_key /etc/letsencrypt/live/domain_name/privkey.pem;</span></span></code></pre></div><p>在我们的例子中，<code>domain_name</code> 是 <code>example.com</code>。</p><h4 id="编辑-nginx-配置" tabindex="-1">编辑 NGINX 配置 <a class="header-anchor" href="#编辑-nginx-配置" aria-label="Permalink to 编辑 NGINX 配置">​</a></h4><p>编辑默认虚拟主机文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># $EDITOR /etc/nginx/sites-available/default</span></span></code></pre></div><p>如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server {</span></span>
<span class="line"><span> listen 80 default_server;</span></span>
<span class="line"><span> listen [::]:80 default_server;</span></span>
<span class="line"><span> server_name www.example.com</span></span>
<span class="line"><span> return 301 https://$server_name$request_uri;</span></span>
<span class="line"><span></span></span>
<span class="line"><span> # SSL configuration</span></span>
<span class="line"><span> #</span></span>
<span class="line"><span> listen 443 ssl default_server;</span></span>
<span class="line"><span> listen [::]:443 ssl default_server;</span></span>
<span class="line"><span> include snippets/secure-example.conf</span></span>
<span class="line"><span> #</span></span>
<span class="line"><span> # Note: You should disable gzip for SSL traffic.</span></span>
<span class="line"><span> # See: https://bugs.debian.org/773332</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>这将启用 NGINX 加密功能。</p><p>保存、退出并检查 NGINX 配置文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># nginx -t</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nginx: the configuration file /etc/nginx/nginx.conf syntax is ok</span></span>
<span class="line"><span>nginx: configuration file /etc/nginx/nginx.conf test is successful</span></span></code></pre></div><p>重启 NGINX：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># systemctl restart nginx</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to 总结">​</a></h3><p>按照上述步骤，此时我们已经拥有了一个安全的基于 NGINX 的 Web 服务器，它由 Certbot 和 Let’s Encrypt 提供加密。这只是一个基本配置，当然你可以使用许多 NGINX 配置参数来个性化所有东西，但这取决于特定的 Web 服务器要求。</p><hr>`,52)),p("p",null,[e[5]||(e[5]=s("via: ")),n(a,{href:"https://www.unixmen.com/encryption-secure-nginx-web-server-ubuntu-16-04/"},{default:t(()=>e[4]||(e[4]=[s("https://www.unixmen.com/encryption-secure-nginx-web-server-ubuntu-16-04/")])),_:1})]),p("p",null,[e[9]||(e[9]=s("作者：")),n(a,{href:"https://www.unixmen.com/author/tutan/"},{default:t(()=>e[6]||(e[6]=[s("Giuseppe Molica")])),_:1}),e[10]||(e[10]=s(" 译者：")),n(a,{href:"https://github.com/geekpi"},{default:t(()=>e[7]||(e[7]=[s("geekpi")])),_:1}),e[11]||(e[11]=s(" 校对：")),n(a,{href:"https://github.com/wxy"},{default:t(()=>e[8]||(e[8]=[s("wxy")])),_:1})]),p("p",null,[e[14]||(e[14]=s("本文由 ")),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>e[12]||(e[12]=[s("LCTT")])),_:1}),e[15]||(e[15]=s(" 原创编译，")),n(a,{href:"https://linux.cn/"},{default:t(()=>e[13]||(e[13]=[s("Linux中国")])),_:1}),e[16]||(e[16]=s(" 荣誉推出"))])])}const y=l(d,[["render",u]]);export{k as __pageData,y as default};
